const sentinelResource = "integration.sentinel"
const sentinelVersion = "0.2.0"
const sentinelCommit = "6645688d08f1505595cae276832a5a5070b82160"
const sentinelPolicySHA256 = "bc866201ed01c9495c5f058af540db264e1a78ce09f2418d34371990bcb4c053"

// Generated by the immutable upstream renderer, not edited or rendered at
// install time. sentinel/provenance.json records its inputs; LICENSE is MIT.
//
//go:embed sentinel/policy.md
var sentinelPolicy string

// SentinelLocations contains only process-observed consumer locations. Empty
// fields use the pinned consumers' defaults under Home, including Windows.
// In particular, ConfigHome is XDG_CONFIG_HOME, not Windows AppData; only
// migration uses it, to find the released OpenCode policy. StateHome is
// XDG_STATE_HOME, which moves the skills CLI lock. KiroHome is the raw
// KIRO_HOME value; kiroHome applies Kiro's own rules for it. CopilotHome is
// COPILOT_HOME, Copilot's configuration directory. Installed names the agents
// whose command or application was discovered (DiscoverSentinelAgents).
type SentinelLocations struct {
	CodexHome, ConfigHome, ClaudeConfigDir, StateHome, KiroHome, CopilotHome string
	Installed                                                                []string
}

// kiroHome resolves Kiro's global directory as Kiro documents KIRO_HOME: an
// absolute path other than a filesystem root, the home directory or one of its
// ancestors. Kiro ignores any other value and uses ~/.kiro, and so does setup.
func kiroHome(home, value string) string {
	fallback := filepath.Join(home, ".kiro")
	if value == "" || !filepath.IsAbs(value) || strings.ContainsAny(value, "\x00\r\n") {
		return fallback
	}
	value = filepath.Clean(value)
	if filepath.Dir(value) == value {
		return fallback
	}
	if relative, err := filepath.Rel(value, home); err == nil && (relative == "." || filepath.IsLocal(relative)) {
		return fallback
	}
	return value
}

// sentinelConsumer is one supported agent's global policy file. Present means
// the agent was observed: its configuration root exists, its command or
// application was discovered, or the bound selection installs its CLI.
type sentinelConsumer struct {
	Agent, Name, Root, Target, Tool string
	Present                         bool
	// Unknown means the root could not be inspected; it is never retired.
	Unknown bool
}

// DiscoverSentinelAgents reports agents whose command, or a Kiro macOS
// application (the IDE or Kiro CLI's own bundle), exists at the process
// boundary. It runs nothing and grants no write authority; configuration roots
// are observed when a selection is bound.
func DiscoverSentinelAgents(target Context, home string) []string {
	found := []string{}
	for _, agent := range []struct {
		name     string
		commands []string
	}{{"codex", []string{"codex"}}, {"claude", []string{"claude"}}, {"copilot", []string{"copilot"}}, {"kiro", []string{"kiro", "kiro-cli"}}} {
		installed := false
		for _, command := range agent.commands {
			_, err := exec.LookPath(command)
			installed = installed || err == nil
		}
		if agent.name == "kiro" && target.OS == "darwin" {
			for _, name := range []string{"Kiro.app", "Kiro CLI.app"} {
				for _, app := range []string{filepath.Join("/Applications", name), filepath.Join(home, "Applications", name)} {
					info, err := os.Stat(app)
					installed = installed || err == nil && info.IsDir()
				}
			}
		}
		if installed {
			found = append(found, agent.name)
		}
	}
	return found
}

// Setup writes policy only for agents that are present, and never creates an
// absent agent's configuration root. Selected is the bound resource closure.
func configureSentinel(d *ProfileDriver, folders ConfigFolders, locations SentinelLocations, selected []string) error {
	if d == nil {
		return errors.New("Sentinel requires the profile publisher")
	}
	for _, item := range []struct {
		value *string
		parts []string
	}{
		{&locations.CodexHome, []string{".codex"}},
		{&locations.ConfigHome, []string{".config"}},
		{&locations.ClaudeConfigDir, []string{".claude"}},
		{&locations.CopilotHome, []string{".copilot"}},
	} {
		if *item.value == "" {
			*item.value = filepath.Join(append([]string{folders.Home}, item.parts...)...)
		}
	}
	for _, path := range []string{folders.Home, locations.CodexHome, locations.ConfigHome, locations.ClaudeConfigDir, locations.CopilotHome} {
		if !filepath.IsAbs(path) || filepath.Clean(path) != path || strings.ContainsAny(path, "\x00\r\n") {
			return errors.New("Sentinel consumer locations must be absolute canonical native paths")
		}
	}
	kiro := kiroHome(folders.Home, locations.KiroHome)
	consumers := []sentinelConsumer{
		{"codex", "Codex", locations.CodexHome, filepath.Join(locations.CodexHome, "AGENTS.md"), "tool.codex", false, false},
		{"claude", "Claude Code", locations.ClaudeConfigDir, filepath.Join(locations.ClaudeConfigDir, "CLAUDE.md"), "tool.claude", false, false},
		{"copilot", "GitHub Copilot", locations.CopilotHome, filepath.Join(locations.CopilotHome, "copilot-instructions.md"), "tool.copilot", false, false},
		{"kiro", "Kiro", kiro, filepath.Join(kiro, "steering", "AGENTS.md"), "tool.kiro", false, false},
	}
	for index := range consumers {
		bound, err := bindConfigDestination(consumers[index].Target)
		if err != nil {
			return err
		}
		consumers[index].Target = bound
		for _, previous := range consumers[:index] {
			if configPathsOverlap(previous.Target, bound) {
				return errors.New("Sentinel consumer policy paths overlap")
			}
		}
	}
	var presence error
	targets := []ProfileTarget{}
	for index, consumer := range consumers {
		_, err := os.Lstat(consumer.Root)
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			consumers[index].Unknown = true
			presence = errors.Join(presence, fmt.Errorf("cannot check whether %s is installed at %s: %w", consumer.Name, consumer.Root, err))
			continue
		}
		consumers[index].Present = err == nil || slices.Contains(locations.Installed, consumer.Agent) || consumer.Tool != "" && slices.Contains(selected, consumer.Tool)
		if consumers[index].Present {
			targets = append(targets, ProfileTarget{consumers[index].Target, sentinelPolicy})
		}
	}
	d.SentinelConsumers = consumers
	if d.Targets == nil {
		d.Targets = map[string][]ProfileTarget{}
	}
	delete(d.Targets, sentinelResource)
	if presence != nil {
		d.recordIssue(sentinelResource, presence)
		return nil
	}
	if len(targets) == 0 {
		d.recordIssue(sentinelResource, errors.New("Sentinel policy found no installed agent. Install Codex, Claude Code, GitHub Copilot or Kiro, or select Codex, Claude Code, Copilot CLI or Kiro CLI here; setup never creates an absent agent's configuration folder"))
		return nil
	}
	d.Targets[sentinelResource] = targets
	return d.validate(sentinelResource)
}

// Saved Sentinel ownership keeps the targets it approved, so update and
// removal still reach every file it wrote. A later agent is a note; reselection
// adds it. A removed agent's target is retired: it is healthy without a block
// and apply never writes it or recreates its folder. The explicit replacement
// of the changed owned policy records that; removal still restores an adopted
// original. With every saved agent removed nothing can be applied, so apply is
// blocked and deselection forgets the absent policy. An agent whose presence
// could not be checked is never retired, and a path outside today's consumer
// locations stays refused.
func retainSentinelTargets(d *ProfileDriver, state State) error {
	receipt := state.Receipts[sentinelResource]
	if receipt.Recovery == "" || receipt.Ownership == "reused" {
		return nil
	}
	if !validProfileRecovery(receipt.Recovery) {
		return errors.New("invalid saved Sentinel recovery path")
	}
	data, err := readDocument(d.baselinePath(receipt.Recovery))
	if errors.Is(err, os.ErrNotExist) && receipt.Status == "in-progress" {
		return nil // The approved targets are the current ones until a baseline exists.
	}
	if err != nil {
		return err
	}
	var baseline profileBaseline
	if err := Decode(data, &baseline); err != nil {
		return err
	}
	if len(baseline.Entries) == 0 || len(baseline.Entries) > len(d.SentinelConsumers) {
		return errors.New("saved Sentinel policy has an invalid consumer list")
	}
	targets, missing, added := []ProfileTarget{}, []string{}, []string{}
	for _, entry := range baseline.Entries {
		index := slices.IndexFunc(d.SentinelConsumers, func(c sentinelConsumer) bool { return c.Target == entry.Path })
		if index < 0 {
			return fmt.Errorf("saved Sentinel policy targets %s, which is not a current consumer location; run setup with the CODEX_HOME, CLAUDE_CONFIG_DIR, COPILOT_HOME and KIRO_HOME used when it was installed to update or remove it (an unreleased earlier target list must be removed before advancing; see docs/UPGRADING.md)", entry.Path)
		}
		target := ProfileTarget{entry.Path, sentinelPolicy}
		if consumer := d.SentinelConsumers[index]; consumer.Unknown {
			return fmt.Errorf("cannot check whether %s is still installed at %s; its saved Sentinel policy is not retired", consumer.Name, consumer.Root)
		} else if !consumer.Present {
			target.Script = ""
			missing = append(missing, consumer.Name+" ("+consumer.Root+")")
		}
		targets = append(targets, target)
	}
	for _, consumer := range d.SentinelConsumers {
		if consumer.Present && !slices.ContainsFunc(targets, func(t ProfileTarget) bool { return t.Path == consumer.Target }) {
			added = append(added, consumer.Name)
		}
	}
	d.Targets = maps.Clone(d.Targets)
	d.Targets[sentinelResource] = targets
	d.Issues = maps.Clone(d.Issues)
	delete(d.Issues, sentinelResource)
	notes := slices.Clone(d.SentinelNotes)
	if len(missing) == len(targets) {
		d.SentinelBlocked = "No agent covered by the saved Sentinel policy is installed any more (" + strings.Join(missing, ", ") + "). Deselect Sentinel policy, or reinstall an agent and choose Update."
	} else if len(missing) != 0 {
		notes = append(notes, strings.Join(missing, ", ")+" is no longer installed; Sentinel policy stops maintaining it and never recreates its folder. To record that, tick the Sentinel policy replacement on the next Choose tools confirmation.")
	}
	if len(added) != 0 {
		notes = append(notes, strings.Join(added, ", ")+" is installed but not covered by the current Sentinel policy. To add it, deselect Sentinel policy and apply, then select it again.")
	}
	d.SentinelNotes = notes
	_, err = d.readBaseline(sentinelResource, receipt)
	return err
}

// These are visible consumer limitations, never write authority. The override
// is inspected only for existence; its personal policy contents are not read.
func sentinelDisclosures(targets []ProfileTarget, consumers []sentinelConsumer) []string {
	result := []string{}
	for _, consumer := range consumers {
		if consumer.Agent != "codex" || !slices.ContainsFunc(targets, func(t ProfileTarget) bool { return t.Path == consumer.Target }) {
			continue
		}
		override := filepath.Join(filepath.Dir(consumer.Target), "AGENTS.override.md")
		_, err := os.Lstat(override)
		if err == nil {
			result = append(result, "Codex may load "+override+" instead of Sentinel's AGENTS.md; reconcile the override manually")
		} else if !errors.Is(err, os.ErrNotExist) {
			result = append(result, fmt.Sprintf("Codex override presence could not be inspected at %s: %v", override, err))
		}
	}
	return result
}
